p.m:
\displaystyle{\begin{aligned}
   \left(-\frac{10}{9}\right) \div (-15)
       \amp = \frac{10}{9} \div 15 \\
       \amp = \frac{10}{9} \div \frac{15}{1} \\
       \amp = \frac{10}{9} \cdot \frac{1}{15} \amp \hbox{We can simplify by dividing 10 and 15 by 5, making the numbers smaller.}\\
       \amp = \frac{2}{9}\cdot \frac{1}{3} \\
       \amp = \frac{2 \cdot 1}{9 \cdot 3} \\
       \amp = \frac{2}{27}
\end{aligned}
    }
